package com.tamako.array.slide_win.find_anagrams;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * @Author:Tamako
 * @Date:2024/4/10 10:21
 * @Description:438. 找到字符串中所有字母异位词
 */
public class Solution {

    //todo 官方的做法，是用26大小的数组，来记录每个字母出现的频次来判断是否为异或词
    public List<Integer> findAnagrams2(String s, String p) {
        int sLen = s.length(), pLen = p.length();

        if (sLen < pLen) {
            return new ArrayList<>();
        }

        List<Integer> ans = new ArrayList<>();
        int[] sCount = new int[26];
        int[] pCount = new int[26];
        for (int i = 0; i < pLen; ++i) {
            ++sCount[s.charAt(i) - 'a'];
            ++pCount[p.charAt(i) - 'a'];
        }

        if (Arrays.equals(sCount, pCount)) {
            ans.add(0);
        }

        for (int i = 0; i < sLen - pLen; ++i) {
            --sCount[s.charAt(i) - 'a'];
            ++sCount[s.charAt(i + pLen) - 'a'];

            if (Arrays.equals(sCount, pCount)) {
                ans.add(i + 1);
            }
        }
        return ans;
    }


    //使用排序来判断是否为异或词，有点费时间
    public List<Integer> findAnagrams(String s, String p) {
        ArrayList<Integer> res = new ArrayList<>();
        int i = 0, j = p.length() - 1;
        char[] pChars = p.toCharArray();
        Arrays.sort(pChars);
        String sortedP = new String(pChars);
        while (j < s.length()) {
            char[] subChars = s.substring(i, j + 1).toCharArray();
            Arrays.sort(subChars);
            String sortedSubStr = new String(subChars);
            if (sortedP.equals(sortedSubStr)) {
                res.add(i);
            }
            if (p.indexOf(s.charAt(j)) != -1) {
                i++;
                j++;
            } else {
                i = j + 1;
                j = i + p.length() - 1;
            }
        }
        return res;
    }

    public static void main(String[] args) {
        String s = "";
        String p = "yqrbgjdwtcaxzsnifvhmou";
        List<Integer> res = new Solution().findAnagrams(s, p);
    }
}
